import{_ as o,c as s,o as i,j as n,Y as r,t as a}from"./chunks/framework.D-NV0Bun.js";const b=JSON.parse('{"title":"gitsubmodules | x-cmd man (git man7) | Mounting one repository inside another","titleTemplate":false,"description":"x-cmd man (git man7 Manual Page) | gitsubmodules - Mounting one repository inside another","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"gitsubmodules | x-cmd man (git man7) | Mounting one repository inside another"}],["meta",{"name":"og:description","content":"x-cmd man (git man7 Manual Page) | gitsubmodules - Mounting one repository inside another"}]]},"headers":[],"params":{"isMan":true,"man":"gitsubmodules","category":"git man7","desc":"Mounting one repository inside another"},"relativePath":"git/man7/gitsubmodules.md","filePath":"git/man7/[man].md"}'),l={name:"git/man7/gitsubmodules.md"},u={class:"visually-hidden"};function d(t,e,c,p,h,g){return i(),s("div",null,[n("h1",u,a(t.$params.man),1),e[0]||(e[0]=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>gitsubmodules - Mounting one repository inside another</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.gitmodules,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $GIT_DIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/config</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> submodule</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">comman</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recurse-submodules</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>A submodule is a repository embedded inside another repository. The submodule has its own history; the repository it is embedded in is called a superproject.</p><p>On the filesystem, a submodule usually (but not always - see FORMS below) consists of (i) a Git directory located under the <strong>$GIT_DIR/modules/</strong> directory of its superproject, (ii) a working directory inside the superproject&#39;s working directory, and a <strong>.git</strong> file at the root of the submodule&#39;s working directory pointing to (i).</p><p>Assuming the submodule has a Git directory at <strong>$GIT_DIR/modules/foo/</strong> and a working directory at <strong>path/to/bar/</strong>, the superproject tracks the submodule via a <strong>gitlink</strong> entry in the tree at <strong>path/to/bar</strong> and an entry in its <strong>.gitmodules</strong> file (see <strong>gitmodules</strong>(5)) of the form <strong>submodule.foo.path = path/to/bar</strong>.</p><p>The <strong>gitlink</strong> entry contains the object name of the commit that the superproject expects the submodule&#39;s working directory to be at.</p><p>The section *<em>submodule.foo.*</em> * in the <strong>.gitmodules</strong> file gives additional hints to Git&#39;s porcelain layer. For example, the <strong>submodule.foo.url</strong> setting specifies where to obtain the submodule.</p><p>Submodules can be used for at least two different use cases:</p><blockquote><p>1.</p><p>Using another project while maintaining independent history. Submodules allow you to contain the working tree of another project within your own working tree while keeping the history of both projects separate. Also, since submodules are fixed to an arbitrary version, the other project can be independently developed without affecting the superproject, allowing the superproject project to fix itself to new versions only when desired.</p></blockquote><blockquote><p>2.</p><p>Splitting a (logically single) project into multiple repositories and tying them back together. This can be used to overcome current limitations of Git&#39;s implementation to have finer grained access:</p><blockquote><p>·</p><p>Size of the Git repository: In its current form Git scales up poorly for large repositories containing content that is not compressed by delta computation between trees. For example, you can use submodules to hold large binary assets and these repositories can be shallowly cloned such that you do not have a large history locally.</p></blockquote><blockquote><p>·</p><p>Transfer size: In its current form Git requires the whole working tree present. It does not allow partial trees to be transferred in fetch or clone. If the project you work on consists of multiple repositories tied together as submodules in a superproject, you can avoid fetching the working trees of the repositories you are not interested in.</p></blockquote><blockquote><p>·</p><p>Access control: By restricting user access to submodules, this can be used to implement read/write policies for different users.</p></blockquote></blockquote><h2 id="the-configuration-of-submodules" tabindex="-1">THE CONFIGURATION OF SUBMODULES <a class="header-anchor" href="#the-configuration-of-submodules" aria-label="Permalink to &quot;THE CONFIGURATION OF SUBMODULES&quot;">​</a></h2><p>Submodule operations can be configured using the following mechanisms (from highest to lowest precedence):</p><blockquote><p>·</p><p>The command line for those commands that support taking submodules as part of their pathspecs. Most commands have a boolean flag <strong>--recurse-submodules</strong> which specify whether to recurse into submodules. Examples are <strong>grep</strong> and <strong>checkout</strong>. Some commands take enums, such as <strong>fetch</strong> and <strong>push</strong>, where you can specify how submodules are affected.</p></blockquote><blockquote><p>·</p><p>The configuration inside the submodule. This includes <strong>$GIT_DIR/config</strong> in the submodule, but also settings in the tree such as a <strong>.gitattributes</strong> or <strong>.gitignore</strong> files that specify behavior of commands inside the submodule.</p><p>For example an effect from the submodule&#39;s <strong>.gitignore</strong> file would be observed when you run <strong>git status --ignore-submodules=none</strong> in the superproject. This collects information from the submodule&#39;s working directory by running <strong>status</strong> in the submodule while paying attention to the <strong>.gitignore</strong> file of the submodule.</p><p>The submodule&#39;s <strong>$GIT_DIR/config</strong> file would come into play when running <strong>git push --recurse-submodules=check</strong> in the superproject, as this would check if the submodule has any changes not published to any remote. The remotes are configured in the submodule as usual in the <strong>$GIT_DIR/config</strong> file.</p></blockquote><blockquote><p>·</p><p>The configuration file <strong>$GIT_DIR/config</strong> in the superproject. Git only recurses into active submodules (see &quot;ACTIVE SUBMODULES&quot; section below).</p><p>If the submodule is not yet initialized, then the configuration inside the submodule does not exist yet, so where to obtain the submodule from is configured here for example.</p></blockquote><blockquote><p>·</p><p>The <strong>.gitmodules</strong> file inside the superproject. A project usually uses this file to suggest defaults for the upstream collection of repositories for the mapping that is required between a submodule&#39;s name and its path.</p><p>This file mainly serves as the mapping between the name and path of submodules in the superproject, such that the submodule&#39;s Git directory can be located.</p><p>If the submodule has never been initialized, this is the only place where submodule configuration is found. It serves as the last fallback to specify where to obtain the submodule from.</p></blockquote><h2 id="forms" tabindex="-1">FORMS <a class="header-anchor" href="#forms" aria-label="Permalink to &quot;FORMS&quot;">​</a></h2><p>Submodules can take the following forms:</p><blockquote><p>·</p><p>The basic form described in DESCRIPTION with a Git directory, a working directory, a <strong>gitlink</strong>, and a <strong>.gitmodules</strong> entry.</p></blockquote><blockquote><p>·</p><p>&quot;Old-form&quot; submodule: A working directory with an embedded <strong>.git</strong> directory, and the tracking <strong>gitlink</strong> and <strong>.gitmodules</strong> entry in the superproject. This is typically found in repositories generated using older versions of Git.</p><p>It is possible to construct these old form repositories manually.</p><p>When deinitialized or deleted (see below), the submodule&#39;s Git directory is automatically moved to <strong>$GIT_DIR/modules/&lt;name&gt;/</strong> of the superproject.</p></blockquote><blockquote><p>·</p><p>Deinitialized submodule: A <strong>gitlink</strong>, and a <strong>.gitmodules</strong> entry, but no submodule working directory. The submodule&#39;s Git directory may be there as after deinitializing the Git directory is kept around. The directory which is supposed to be the working directory is empty instead.</p><p>A submodule can be deinitialized by running <strong>git submodule deinit</strong>. Besides emptying the working directory, this command only modifies the superproject&#39;s <strong>$GIT_DIR/config</strong> file, so the superproject&#39;s history is not affected. This can be undone using <strong>git submodule init</strong>.</p></blockquote><blockquote><p>·</p><p>Deleted submodule: A submodule can be deleted by running <strong>git rm &lt;submodule path&gt; &amp;&amp; git commit</strong>. This can be undone using <strong>git revert</strong>.</p><p>The deletion removes the superproject&#39;s tracking data, which are both the <strong>gitlink</strong> entry and the section in the <strong>.gitmodules</strong> file. The submodule&#39;s working directory is removed from the file system, but the Git directory is kept around as it to make it possible to checkout past commits without requiring fetching from another repository.</p><p>To completely remove a submodule, manually delete <strong>$GIT_DIR/modules/&lt;name&gt;/</strong>.</p></blockquote><h2 id="active-submodules" tabindex="-1">ACTIVE SUBMODULES <a class="header-anchor" href="#active-submodules" aria-label="Permalink to &quot;ACTIVE SUBMODULES&quot;">​</a></h2><p>A submodule is considered active,</p><blockquote><p>1.</p><p>if <strong>submodule.&lt;name&gt;.active</strong> is set to <strong>true</strong></p><p>or</p></blockquote><blockquote><p>2.</p><p>if the submodule&#39;s path matches the pathspec in <strong>submodule.active</strong></p><p>or</p></blockquote><blockquote><p>3.</p><p>if <strong>submodule.&lt;name&gt;.url</strong> is set.</p></blockquote><p>and these are evaluated in this order.</p><p>For example:</p><blockquote><pre><code>[submodule &quot;foo&quot;]
  active = false
  url = https://example.org/foo
[submodule &quot;bar&quot;]
  active = true
  url = https://example.org/bar
[submodule &quot;baz&quot;]
  url = https://example.org/baz
</code></pre></blockquote><p>In the above config only the submodule <em>bar</em> and <em>baz</em> are active, <em>bar</em> due to (1) and <em>baz</em> due to (3). <em>foo</em> is inactive because (1) takes precedence over (3)</p><p>Note that (3) is a historical artefact and will be ignored if the (1) and (2) specify that the submodule is not active. In other words, if we have a <strong>submodule.&lt;name&gt;.active</strong> set to <strong>false</strong> or if the submodule&#39;s path is excluded in the pathspec in <strong>submodule.active</strong>, the url doesn&#39;t matter whether it is present or not. This is illustrated in the example that follows.</p><blockquote><pre><code>[submodule &quot;foo&quot;]
  active = true
  url = https://example.org/foo
[submodule &quot;bar&quot;]
  url = https://example.org/bar
[submodule &quot;baz&quot;]
  url = https://example.org/baz
[submodule &quot;bob&quot;]
  ignore = true
[submodule]
  active = b*
  active = :(exclude) baz
</code></pre></blockquote><p>In here all submodules except <em>baz</em> (foo, bar, bob) are active. <em>foo</em> due to its own active flag and all the others due to the submodule active pathspec, which specifies that any submodule starting with <em>b</em> except <em>baz</em> are also active, regardless of the presence of the .url field.</p><h2 id="workflow-for-a-third-party-library" tabindex="-1">WORKFLOW FOR A THIRD PARTY LIBRARY <a class="header-anchor" href="#workflow-for-a-third-party-library" aria-label="Permalink to &quot;WORKFLOW FOR A THIRD PARTY LIBRARY&quot;">​</a></h2><blockquote><pre><code># Add a submodule
git submodule add &lt;URL&gt; &lt;path&gt;
</code></pre></blockquote><blockquote><pre><code># Occasionally update the submodule to a new version:
git -C &lt;path&gt; checkout &lt;new version&gt;
git add &lt;path&gt;
git commit -m &quot;update submodule to new version&quot;
</code></pre></blockquote><blockquote><pre><code># See the list of submodules in a superproject
git submodule status
</code></pre></blockquote><blockquote><pre><code># See FORMS on removing submodules
</code></pre></blockquote><h2 id="workflow-for-an-artificially-split-repo" tabindex="-1">WORKFLOW FOR AN ARTIFICIALLY SPLIT REPO <a class="header-anchor" href="#workflow-for-an-artificially-split-repo" aria-label="Permalink to &quot;WORKFLOW FOR AN ARTIFICIALLY SPLIT REPO&quot;">​</a></h2><blockquote><pre><code># Enable recursion for relevant commands, such that
# regular commands recurse into submodules by default
git config --global submodule.recurse true
</code></pre></blockquote><blockquote><pre><code># Unlike most other commands below, clone still needs
# its own recurse flag:
git clone --recurse &lt;URL&gt; &lt;directory&gt;
cd &lt;directory&gt;
</code></pre></blockquote><blockquote><pre><code># Get to know the code:
git grep foo
git ls-files --recurse-submodules
</code></pre></blockquote><blockquote><p><br> &gt; <strong>Note</strong></p><p><br> &gt; <strong>git ls-files</strong> also requires its own <strong>--recurse-submodules</strong> flag.</p></blockquote><blockquote><pre><code># Get new code
git fetch
git pull --rebase
</code></pre></blockquote><blockquote><pre><code># Change worktree
git checkout
git reset
</code></pre></blockquote><h2 id="implementation-details" tabindex="-1">IMPLEMENTATION DETAILS <a class="header-anchor" href="#implementation-details" aria-label="Permalink to &quot;IMPLEMENTATION DETAILS&quot;">​</a></h2><p>When cloning or pulling a repository containing submodules the submodules will not be checked out by default; you can instruct <strong>clone</strong> to recurse into submodules. The <strong>init</strong> and <strong>update</strong> subcommands of <strong>git submodule</strong> will maintain submodules checked out and at an appropriate revision in your working tree. Alternatively you can set <strong>submodule.recurse</strong> to have <strong>checkout</strong> recursing into submodules (note that <strong>submodule.recurse</strong> also affects other Git commands, see <strong>git-config</strong>(1) for a complete list).</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-submodule</strong>(1), <strong>gitmodules</strong>(5).</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,55))])}const f=o(l,[["render",d]]);export{b as __pageData,f as default};
